// ─── MCP Handlers (authenticated tool calls) ────────────────────────
// Pass directly to OAuthProvider as apiHandlers so ctx.props (set by
// the OAuthProvider after token validation) flows through correctly.
const sseHandler = withConnectionProps(RelayMCP.serveSSE("/sse") as unknown as WorkerHandler);
const mcpHandler = withConnectionProps(RelayMCP.serve("/mcp") as unknown as WorkerHandler);

/**
 * mcp-usage-accounting.RECORD.7 — adds the connection (OAuth grant id) to the session's props, so each call is
 * counted on its connection. The library has already validated the token when these handlers run, and its tokens
 * are `<userId>:<grantId>:<secret>`, so the grant id read from it is the one the library just accepted; it is only
 * attached when the token's user is the props' account.
 */
export function attachGrantToProps(request: Request, ctx: { props?: unknown }): void {
  const auth = request.headers.get("Authorization");
  const ref = grantRefFromToken(auth?.startsWith("Bearer ") ? auth.slice(7) : null);
  const props = ctx.props as { accountRef?: unknown } | undefined;
  if (!ref || !props || typeof props !== "object" || props.accountRef !== ref.userId) return;
  ctx.props = { ...props, grantId: ref.grantId };
}

function withConnectionProps(handler: WorkerHandler): WorkerHandler {
  return {
    fetch(request: Request, env: any, ctx: any) {
      try {
        attachGrantToProps(request, ctx);
      } catch {
        // Counting never stands in the way of a call.
      }
      return handler.fetch(request, env, ctx);
    },
  };
}

// ─── Non-OAuth routes ─────────────────────────────────────────────────

const outerApp = new Hono<{ Bindings: Env }>();

/**
 * A problem document that also keeps the `{error, error_description}` pair
 * these endpoints answered before, for callers that already read it.
 */
function legacyProblem(
  status: number,
  code: string,
  error: string,
  description: string,
  headers?: HeadersInit,
): Response {
  return problem({ status, code, detail: description, headers, extra: { error, error_description: description } });
}

/** Methods each outer route answers, for 405 + Allow instead of a bare 404. */
const OUTER_ROUTE_METHODS: { pattern: RegExp; allow: string }[] = [
  { pattern: /^\/\.well-known\/openai-apps-challenge$/, allow: "GET, HEAD" },
  { pattern: /^\/ws\/auth$/, allow: "POST, OPTIONS" },
  { pattern: /^\/ws\/ext$/, allow: "GET" },
  { pattern: /^\/ext\/connect-code\/(start|status)$/, allow: "POST, OPTIONS" },
  { pattern: /^\/ext\/connections$/, allow: "GET, OPTIONS" },
  { pattern: /^\/ext\/connections\/[^/]+$/, allow: "DELETE, OPTIONS" },
  { pattern: /^\/ext\/usage$/, allow: "GET, OPTIONS" },
  { pattern: /^\/ext\/usage\/local$/, allow: "POST, OPTIONS" },
  { pattern: /^\/admin\/usage$/, allow: "GET" },
  { pattern: /^\/transparency(\/(latest|verify|gaps))?$/, allow: "GET, HEAD" },
  { pattern: /^\/transparency\/append$/, allow: "POST" },
];

outerApp.notFound((c) => {
  const { pathname } = new URL(c.req.url);
  const route = OUTER_ROUTE_METHODS.find((r) => r.pattern.test(pathname));
  if (route) {
    return problem({
      status: 405,
      code: "method_not_allowed",
      detail: `${c.req.method} is not supported here. Allowed: ${route.allow}.`,
      headers: { Allow: route.allow },
    });
  }
  return problem({ status: 404, code: "not_found", detail: `No resource at ${pathname}.` });
});

outerApp.onError((err, c) => {
  console.error(`[worker] ${c.req.method} ${new URL(c.req.url).pathname} failed:`, err?.message || err);
  return problem({ status: 500, code: "internal_error", detail: "Internal error" });
});

const MCP_ORIGIN = "https://mcp.kaptionai.com";
const LEGACY_MCP_ORIGIN = "https://mcp-ext.kaptionai.com";
const MCP_ORIGINS = new Set([MCP_ORIGIN, LEGACY_MCP_ORIGIN]);
const LEGACY_HOME_REDIRECT = "https://kaptionai.com/mcp/";
const OPENAI_CHALLENGE_PATH = "/.well-known/openai-apps-challenge";

/**
 * Keep OAuth discovery bound to the hostname the client actually selected.
 * Both production domains reach the same worker, but RFC 9728 clients compare
 * the advertised protected resource with the URL they connected to. Unknown
 * worker/dev hosts deliberately fall back to the canonical production origin
 * rather than becoming attacker-controlled OAuth issuers through Host spoofing.
 */
export function getMcpOrigin(requestUrl: URL): string {
  return MCP_ORIGINS.has(requestUrl.origin) ? requestUrl.origin : MCP_ORIGIN;
}

// OpenAI provides the token during portal domain verification. Keeping it in
// an environment secret lets the well-known endpoint return exactly one token
// without a deploy or a repository-stored credential.
outerApp.get(OPENAI_CHALLENGE_PATH, (c) => {
  const token = c.env.OPENAI_APPS_CHALLENGE_TOKEN?.trim();
  if (!token) return problem({ status: 404, code: "not_configured", detail: "Not configured" });
  return c.text(token, 200, { "Cache-Control": "no-store" });
});

// CORS preflight for /ws/auth — needed for Chrome extension fetch (no host_permissions)
outerApp.options("/ws/auth", (c) => {
  return new Response(null, {
    status: 204,
    headers: {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "POST, OPTIONS",
      "Access-Control-Allow-Headers": "Authorization, Content-Type",
      "Access-Control-Max-Age": "86400",
    },
  });
});

// mcp.CLOUD_RELAY.3 — JWT→wstoken exchange, 60s single-use KV TTL
outerApp.post("/ws/auth", async (c) => {
  try {
    const auth = c.req.header("Authorization");
    if (!auth?.startsWith("Bearer ")) {
      return legacyProblem(401, "missing_bearer_token", "invalid_request", "Missing bearer token");
    }
    const jwt = auth.slice(7);

    // Validate JWT and extract phone → accountRef
    const phone = await validateJwt(c.env.JWT_SECRET, jwt);
    if (!phone) {
      return legacyProblem(401, "invalid_token", "invalid_token", "Invalid JWT");
    }
    const accountRef = await deriveAccountRef(phone, c.env.PHONE_REF_SECRET);
    if (!accountRef) {
      return legacyProblem(401, "invalid_token", "invalid_token", "Invalid JWT");
    }

    // Generate single-use token, store in KV with a 60 s TTL
    const token = crypto.randomUUID();
    await c.env.OAUTH_KV.put(`ws-auth:${token}`, accountRef, { expirationTtl: 60 });

    return c.json({ token }, 200, { "Access-Control-Allow-Origin": "*" });
  } catch (e: any) {
    console.error("[ws/auth] Token exchange error:", e?.message || e);
    return legacyProblem(500, "internal_error", "server_error", "Internal error");
  }
});

// [H6] WebSocket endpoint — token validated via auth handshake in RelayRoom
outerApp.get("/ws/ext", async (c) => {
  const upgradeHeader = c.req.header("Upgrade");
  if (upgradeHeader !== "websocket") {
    return legacyProblem(426, "upgrade_required", "invalid_request", "Expected WebSocket upgrade", { Upgrade: "websocket" });
  }

  const url = new URL(c.req.url);

  // Support ?wstoken= (short-lived, preferred), ?phone= (legacy), ?token= (extension session), ?jwt= (JWT auth)
  let accountRefHint: string | null = null;
  const wstoken = url.searchParams.get("wstoken");
  const phoneHint = url.searchParams.get("phone");
  const token = url.searchParams.get("token");
  const jwt = url.searchParams.get("jwt");

  // Preferred: short-lived single-use token from POST /ws/auth
  if (wstoken) {
    const ref = await c.env.OAUTH_KV.get(`ws-auth:${wstoken}`);
    if (!ref) {
      return legacyProblem(401, "invalid_token", "invalid_token", "Invalid or expired wstoken");
    }
    accountRefHint = ref;
    // Single-use: delete immediately
    c.executionCtx.waitUntil(c.env.OAUTH_KV.delete(`ws-auth:${wstoken}`));
  }

  if (!accountRefHint && phoneHint) {
    accountRefHint = await deriveAccountRef(phoneHint, c.env.PHONE_REF_SECRET);
  }

  if (!accountRefHint && jwt) {
    // mcp.CLOUD_RELAY.14 — the JWT's signature is checked here too, not only its payload read.
    const jwtPhone = await validateJwt(c.env.JWT_SECRET, jwt);
    if (!jwtPhone) {
      return legacyProblem(401, "invalid_token", "invalid_token", "Invalid JWT");
    }
    accountRefHint = await deriveAccountRef(jwtPhone, c.env.PHONE_REF_SECRET);
  }

  if (!accountRefHint && token) {
    const session = await validateExtensionSession(
      c.env.OAUTH_KV,
      token,
      c.env.EPHEMERAL_STATE_SECRET,
    );
    if (!session) {
      return legacyProblem(401, "invalid_token", "invalid_token", "Invalid or expired token");
    }
    accountRefHint = session.accountRef;
  }

  if (!accountRefHint) {
    return legacyProblem(400, "missing_credentials", "invalid_request", "Missing phone, token, jwt, or wstoken parameter");
  }

  // Route to the RelayRoom for this account reference via fetch (not RPC)
  // to properly handle WebSocket upgrade across DO boundary
  const roomId = c.env.RELAY_ROOM.idFromName(accountRefHint);
  const room = c.env.RELAY_ROOM.get(roomId);
  // mcp.CLOUD_RELAY.14 — the room learns whose it is from us, never from the client (any value it sent is replaced):
  // the handshake then only counts for that account.
  const forwarded = new Request(c.req.raw);
  forwarded.headers.set(ROOM_ACCOUNT_HEADER, accountRefHint);
  return room.fetch(forwarded);
});

// mcp.CLOUD_RELAY.12 — the extension's "Connected apps" list: the AI apps
// connected to this WhatsApp account, and a way to disconnect one. The
// extension calls these from its service worker with its Kaption JWT.
const CONNECTIONS_CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, DELETE, OPTIONS",
  "Access-Control-Allow-Headers": "Authorization",
  "Access-Control-Max-Age": "86400",
};

function unauthorizedConnections(): Response {
  return problem({
    status: 401,
    code: "invalid_token",
    detail: "Send the extension's Kaption JWT as a Bearer token.",
    headers: { ...CONNECTIONS_CORS, "WWW-Authenticate": 'Bearer realm="kaption-extension"' },
    extra: { error: "Unauthorized" },
  });
}

/**
 * The accounts a Kaption JWT speaks for: its phone's, then (mcp.CLOUD_RELAY.17) the same Brazilian mobile line written
 * the other way, so connections made with either form are listed and can be disconnected. Empty when unauthorized.
 */
async function accountsFromBearer(authorization: string | undefined, env: Env): Promise<string[]> {
  if (!authorization?.startsWith("Bearer ")) return [];
  const phone = await validateJwt(env.JWT_SECRET, authorization.slice(7));
  if (!phone) return [];
  return accountRefsForPhone(phone, env.PHONE_REF_SECRET);
}

// getOAuthApi needs the provider's options but never serves pages itself.
const HELPERS_ONLY_HANDLER = { fetch: async () => new Response("Not found", { status: 404 }) };

function oauthApi(env: Env) {
  return getOAuthApi(buildOAuthOptions(MCP_ORIGIN, HELPERS_ONLY_HANDLER), env);
}

// mcp.CONNECT_CODE.1-2 — "Add to Claude": the extension asks for a connect code. Its JWT names the phone (and keeps
// strangers from spending our API calls); the proof is the WhatsApp handshake the extension then sends.
const CONNECT_CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers": "Authorization, Content-Type",
  "Access-Control-Max-Age": "86400",
};

outerApp.options("/ext/connect-code/start", () => new Response(null, { status: 204, headers: CONNECT_CORS }));
outerApp.options("/ext/connect-code/status", () => new Response(null, { status: 204, headers: CONNECT_CORS }));

outerApp.post("/ext/connect-code/start", async (c) => {
  const auth = c.req.header("Authorization");
  const phone = auth?.startsWith("Bearer ") ? await validateJwt(c.env.JWT_SECRET, auth.slice(7)) : null;
  if (!phone) return legacyProblem(401, "invalid_token", "invalid_token", "Invalid or missing Kaption JWT", CONNECT_CORS);
  const accountRef = await deriveAccountRef(phone, c.env.PHONE_REF_SECRET);
  if (!accountRef) return legacyProblem(401, "invalid_token", "invalid_token", "Invalid or missing Kaption JWT", CONNECT_CORS);
  const limit = await startLimit(c.env.OAUTH_KV, accountRef);
  if (!limit.allowed) {
    return tooManyRequests(limit.status, "Too many connect codes requested for this phone. Try again later.", {
      headers: CONNECT_CORS,
      extra: { error: "rate_limited" },
    });
  }
  const headers = { ...CONNECT_CORS, ...rateLimitHeaders(limit.status) };
  try {
    const started = await startConnectPairing(connectDeps(c.env), phone);
    if (!started) {
      return problem({
        status: 502,
        code: "handshake_unavailable",
        detail: "Kaption's WhatsApp handshake service did not answer. Try again.",
        headers,
        extra: { error: "handshake_unavailable" },
      });
    }
    return c.json(started, 200, headers);
  } catch (e: any) {
    console.error("[connect-code] start failed:", e?.message || e);
    return legacyProblem(500, "internal_error", "server_error", "Internal error", headers);
  }
});

outerApp.post("/ext/connect-code/status", async (c) => {
  const auth = c.req.header("Authorization");
  const phone = auth?.startsWith("Bearer ") ? await validateJwt(c.env.JWT_SECRET, auth.slice(7)) : null;
  if (!phone) return legacyProblem(401, "invalid_token", "invalid_token", "Invalid or missing Kaption JWT", CONNECT_CORS);
  let body: { pairId?: unknown } = {};
  try { body = await c.req.json(); } catch { body = {}; }
  try {
    const status = await pollConnectPairing(connectDeps(c.env), String(body.pairId ?? ""), phone);
    return c.json(status, 200, CONNECT_CORS);
  } catch (e: any) {
    console.error("[connect-code] status failed:", e?.message || e);
    return problem({ status: 500, code: "internal_error", detail: "Internal error", headers: CONNECT_CORS });
  }
});

outerApp.options("/ext/connections", () => new Response(null, { status: 204, headers: CONNECTIONS_CORS }));
outerApp.options("/ext/connections/:grantId", () => new Response(null, { status: 204, headers: CONNECTIONS_CORS }));

outerApp.get("/ext/connections", async (c) => {
  const userIds = await accountsFromBearer(c.req.header("Authorization"), c.env);
  if (userIds.length === 0) return unauthorizedConnections();
  try {
    const helpers = oauthApi(c.env);
    const [lists, usage] = await Promise.all([
      Promise.all(userIds.map((userId) => listConnections(helpers, c.env.OAUTH_KV, userId))),
      // mcp-usage-accounting.REPORT.2 — this month's calls per connection; the list never fails over it.
      monthUsageByConnection(c.env, userIds, Date.now()).catch((e: any) => {
        console.error("[connections] usage failed:", e?.message || e);
        return null;
      }),
    ]);
    const connections = lists
      .flat()
      .sort((a, b) => b.connectedAt - a.connectedAt)
      .map((connection) =>
        usage
          ? { ...connection, usage: usage.byConnection.get(connection.id) ?? { month: usage.month, calls: 0, ok: 0 } }
          : connection,
      );
    return c.json({ connections }, 200, { ...CONNECTIONS_CORS, "Cache-Control": "no-store" });
  } catch (e: any) {
    console.error("[connections] list failed:", e?.message || e);
    return problem({ status: 500, code: "internal_error", detail: "Could not load connections", headers: CONNECTIONS_CORS, extra: { error: "Could not load connections" } });
  }
});

outerApp.delete("/ext/connections/:grantId", async (c) => {
  const userIds = await accountsFromBearer(c.req.header("Authorization"), c.env);
  if (userIds.length === 0) return unauthorizedConnections();
  const grantId = c.req.param("grantId");
  if (!/^[^\s:/]{1,256}$/.test(grantId)) {
    return problem({ status: 400, code: "invalid_connection_id", detail: "Invalid connection id", headers: CONNECTIONS_CORS, extra: { error: "Invalid connection id" } });
  }
  try {
    // revokeGrant is scoped to this account's own grants (each form's; a grant id belongs to at most one).
    const helpers = oauthApi(c.env);
    for (const userId of userIds) await disconnect(helpers, c.env.OAUTH_KV, userId, grantId);
    return c.json({ ok: true }, 200, CONNECTIONS_CORS);
  } catch (e: any) {
    console.error("[connections] disconnect failed:", e?.message || e);
    return problem({ status: 500, code: "internal_error", detail: "Could not disconnect", headers: CONNECTIONS_CORS, extra: { error: "Could not disconnect" } });
  }
});

// ─── Claude and ChatGPT usage (spec mcp-usage-accounting) ─────────────

const USAGE_CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Authorization, Content-Type",
  "Access-Control-Max-Age": "86400",
};

/** The accounts' ledgers merged: a Brazilian line's two forms are two accounts (mcp.CLOUD_RELAY.17). */
async function mergedLedgers(env: Env, userIds: string[], month: string) {
  const reports = await Promise.all(userIds.map((userId) => ledgerFor(env, userId).report(month)));
  const rows: DayRow[] = reports.flatMap((r) => r.rows);
  const connections: ConnectionRow[] = reports.flatMap((r) => r.connections);
  const since = reports.map((r) => r.since).filter((d): d is string => !!d).sort()[0] ?? null;
  return { rows, connections, since };
}

/** mcp-usage-accounting.REPORT.2 — this month's calls per connection, for Connected apps. */
async function monthUsageByConnection(env: Env, userIds: string[], now: number) {
  const month = monthOf(now);
  const { rows } = await mergedLedgers(env, userIds, month);
  const byConnection = new Map<string, { month: string; calls: number; ok: number }>();
  for (const row of rows) {
    const entry = byConnection.get(row.connection) ?? { month, calls: 0, ok: 0 };
    entry.calls += row.calls;
    if (row.outcome === "ok") entry.ok += row.calls;
    byConnection.set(row.connection, entry);
  }
  return { month, byConnection };
}

outerApp.options("/ext/usage", () => new Response(null, { status: 204, headers: USAGE_CORS }));
outerApp.options("/ext/usage/local", () => new Response(null, { status: 204, headers: USAGE_CORS }));

// mcp-usage-accounting.REPORT.1 — the caller's own usage this month (or ?month=YYYY-MM): by app, connection, tool, day.
outerApp.get("/ext/usage", async (c) => {
  const userIds = await accountsFromBearer(c.req.header("Authorization"), c.env);
  if (userIds.length === 0) return unauthorizedConnections();
  const now = Date.now();
  const month = c.req.query("month") || monthOf(now);
  if (!monthRange(month)) {
    return problem({ status: 400, code: "invalid_month", detail: "month must be YYYY-MM.", headers: USAGE_CORS });
  }
  try {
    const [{ rows, connections, since }, grants] = await Promise.all([
      mergedLedgers(c.env, userIds, month),
      activeGrantIds(c.env, userIds),
    ]);
    const report = buildReport(month, rows, connections, since, grants, now);
    return c.json(report, 200, { ...USAGE_CORS, "Cache-Control": "no-store" });
  } catch (e: any) {
    console.error("[usage] report failed:", e?.message || e);
    return problem({ status: 500, code: "internal_error", detail: "Could not load usage", headers: USAGE_CORS });
  }
});

// mcp-usage-accounting.LOCAL.5-8 — the extension's batched counters for calls from local apps (the local hub).
outerApp.post("/ext/usage/local", async (c) => {
  const userIds = await accountsFromBearer(c.req.header("Authorization"), c.env);
  if (userIds.length === 0) return unauthorizedConnections();
  const text = await c.req.text();
  if (text.length > LOCAL_MAX_BODY_BYTES) {
    return problem({ status: 413, code: "usage_batch_too_large", detail: "The batch is larger than 64 KB.", headers: USAGE_CORS });
  }
  let body: unknown;
  try {
    body = JSON.parse(text);
  } catch {
    body = null;
  }
  const parsed = parseLocalBatch(body, Date.now());
  if ("error" in parsed) {
    return problem({ status: 400, code: "invalid_usage_batch", detail: parsed.error, headers: USAGE_CORS });
  }
  if (c.env.USAGE_LEDGER_ENABLED === "off") {
    return c.json({ ok: true, accepted: 0, duplicate: false, recording: false }, 200, USAGE_CORS);
  }
  try {
    // The account's own form (the one its extension signs in with).
    const result = await ledgerFor(c.env, userIds[0]).record(parsed.cells, {
      batchId: `local:${parsed.batchId}`,
      accountTag: userIds[0],
    });
    return c.json({ ok: true, ...result }, 200, USAGE_CORS);
  } catch (e: any) {
    console.error("[usage] local batch failed:", e?.message || e);
    return problem({ status: 500, code: "internal_error", detail: "Could not record usage", headers: USAGE_CORS });
  }
});

/** The account's cloud connections that still exist (grant ids). */
async function activeGrantIds(env: Env, userIds: string[]): Promise<Set<string>> {
  const helpers = oauthApi(env);
  const ids = new Set<string>();
  for (const userId of userIds) {
    let cursor: string | undefined;
    do {
      const page = await helpers.listUserGrants(userId, { cursor, limit: 100 });
      for (const grant of page.items) ids.add(grant.id);
      cursor = page.cursor;
    } while (cursor);
  }
  return ids;
}

/** Constant-time comparison of two strings. */
function sameSecret(a: string, b: string): boolean {
  if (!a || !b) return false;
  const left = new TextEncoder().encode(a);
  const right = new TextEncoder().encode(b);
  let diff = left.length ^ right.length;
  for (let i = 0; i < Math.max(left.length, right.length); i++) diff |= (left[i] ?? 0) ^ (right[i] ?? 0);
  return diff === 0;
}

// mcp-usage-accounting.ADMIN.1-2 — aggregate usage over every account (no account, no connection), for Kaption's
// internal services holding the internal API key. ?from=YYYY-MM-DD&to=YYYY-MM-DD (to exclusive; default this month).
outerApp.get("/admin/usage", async (c) => {
  const auth = c.req.header("Authorization") ?? "";
  if (!auth.startsWith("Bearer ") || !sameSecret(auth.slice(7), c.env.INTERNAL_API_KEY ?? "")) {
    return problem({ status: 401, code: "unauthorized", detail: "Unauthorized" });
  }
  const now = Date.now();
  const month = monthRange(monthOf(now))!;
  const day = /^\d{4}-\d{2}-\d{2}$/;
  const from = day.test(c.req.query("from") ?? "") ? c.req.query("from")! : dayOf(month.from);
  const to = day.test(c.req.query("to") ?? "") ? c.req.query("to")! : dayOf(month.to);
  if (!c.env.USAGE_TOTALS) return c.json({ from, to, rows: [], accounts: [] });
  const totals = c.env.USAGE_TOTALS.get(c.env.USAGE_TOTALS.idFromName("global"));
  return c.json({ from, to, ...(await totals.report(from, to)) }, 200, { "Cache-Control": "no-store" });
});

// Transparency endpoints

// Enrich chain entries with a public Rekor URL for easy verification
function withRekorUrl<T extends { event: { rekorLogIndex: string } }>(entry: T): T & { rekorUrl?: string } {
  const idx = entry.event.rekorLogIndex;
  return idx && idx !== "unknown"
    ? { ...entry, rekorUrl: `https://search.sigstore.dev/?logIndex=${idx}` }
    : entry;
}

outerApp.get("/transparency", async (c) => {
  const chainId = c.env.DEPLOYMENT_CHAIN.idFromName("main");
  const chain = c.env.DEPLOYMENT_CHAIN.get(chainId);
  const limit = Math.min(parseInt(c.req.query("limit") || "100", 10), 100);
  const offset = Math.max(parseInt(c.req.query("offset") || "0", 10), 0);
  const history = await chain.getHistory(limit, offset);
  return c.json({ ...history, entries: history.entries.map(withRekorUrl) });
});

outerApp.get("/transparency/latest", async (c) => {
  const chainId = c.env.DEPLOYMENT_CHAIN.idFromName("main");
  const chain = c.env.DEPLOYMENT_CHAIN.get(chainId);
  const latest = await chain.getLatest();
  return c.json(latest ? withRekorUrl(latest) : { message: "No deployments recorded" });
});

outerApp.get("/transparency/verify", async (c) => {
  const chainId = c.env.DEPLOYMENT_CHAIN.idFromName("main");
  const chain = c.env.DEPLOYMENT_CHAIN.get(chainId);
  const result = await chain.verifyChain();
  return c.json(result);
});

outerApp.get("/transparency/gaps", async (c) => {
  const cfToken = c.req.header("Authorization")?.replace("Bearer ", "");
  const accountId = c.req.query("account_id");

  if (!cfToken || !accountId) {
    const detail = "Provide Authorization: Bearer <CF_TOKEN> and ?account_id=<ID>";
    return problem({ status: 400, code: "missing_parameters", detail, extra: { error: detail } });
  }

  // Guard against path/SSRF injection before interpolating into the CF API URL —
  // Cloudflare account IDs are exactly 32 lowercase hex characters.
  if (!/^[0-9a-f]{32}$/.test(accountId)) {
    const detail = "Invalid account_id (expected 32 hex characters)";
    return problem({ status: 400, code: "invalid_account_id", detail, extra: { error: detail } });
  }

  // Fetch CF deployment history
  const cfRes = await fetch(
    `https://api.cloudflare.com/client/v4/accounts/${accountId}/workers/scripts/mcp-remote/deployments`,
    { headers: { Authorization: `Bearer ${cfToken}` } },
  );
  if (!cfRes.ok) {
    return problem({
      status: 502,
      code: "upstream_error",
      detail: "Failed to fetch CF deployments",
      extra: { error: "Failed to fetch CF deployments", upstream_status: cfRes.status },
    });
  }
  const cfData = (await cfRes.json()) as {
    result?: { deployments?: { id: string; created_on: string; source?: string }[] };
  };
  const cfDeployments = cfData.result?.deployments ?? [];

  // Load chain entries
  const chainId = c.env.DEPLOYMENT_CHAIN.idFromName("main");
  const chain = c.env.DEPLOYMENT_CHAIN.get(chainId);
  const { entries } = await chain.getHistory(100, 0);

  const attestedIds = new Set(entries.filter(e => e.event.cfVersionId).map(e => e.event.cfVersionId));
  const firstAttested = entries.find(e => e.event.cfVersionId);
  const cutoff = firstAttested?.event.deployedAt;

  const gaps = cfDeployments.filter(d => {
    if (attestedIds.has(d.id)) return false;
    if (cutoff && d.created_on <= cutoff) return false; // pre-attestation era
    return true;
  });

  return c.json({
    cfVersions: cfDeployments.length,
    chainEntries: entries.length,
    attestedVersions: attestedIds.size,
    gaps: gaps.map(d => ({ id: d.id, created_on: d.created_on, source: d.source })),
    clean: gaps.length === 0,
  });
});

outerApp.post("/transparency/append", async (c) => {
  const apiKey = c.req.header("Authorization")?.replace("Bearer ", "");
  if (!c.env.DEPLOY_API_KEY || apiKey !== c.env.DEPLOY_API_KEY) {
    return problem({ status: 401, code: "unauthorized", detail: "Unauthorized", extra: { error: "Unauthorized" } });
  }

  let event: unknown;
  try {
    event = await c.req.json();
  } catch {
    return problem({ status: 400, code: "invalid_json", detail: "Invalid JSON body" });
  }
  const chainId = c.env.DEPLOYMENT_CHAIN.idFromName("main");
  const chain = c.env.DEPLOYMENT_CHAIN.get(chainId);
  const result = await chain.appendDeployment(event as any);
  return c.json(result);
});

// ─── Bearer challenges as JSON ────────────────────────────────────────

/**
 * The OAuth library answers a request without a token with an empty 401 body
 * and a bad token with `{error, error_description}`. Some MCP clients and
 * registries read the body rather than the header, so every Bearer 401 gets
 * an RFC 9457 problem body (code `authentication_required` without a token,
 * else the challenge's error, e.g. `invalid_token`) that keeps the RFC 6750
 * `error` / `error_description` pair and names the RFC 9728 metadata URL.
 * The status and every header — above all `WWW-Authenticate` — pass through
 * untouched; only the body and Content-Type change.
 */
export async function toJsonBearerChallenge(response: Response, requestUrl: URL): Promise<Response> {
  if (response.status !== 401) return response;
  const challenge = response.headers.get("WWW-Authenticate");
  if (!challenge || !/^Bearer\b/i.test(challenge)) return response;

  const resourceMetadata =
    /resource_metadata="([^"]+)"/.exec(challenge)?.[1]
    ?? `${getMcpOrigin(requestUrl)}/.well-known/oauth-protected-resource${requestUrl.pathname}`;
  const challengeError = /\berror="([^"]+)"/.exec(challenge)?.[1];

  let upstream: { error?: unknown; error_description?: unknown } = {};
  try {
    const text = await response.text();
    if (text) upstream = JSON.parse(text);
  } catch {
    // Not JSON — fall back to what the challenge says.
  }

  const error =
    typeof upstream.error === "string" ? upstream.error : challengeError ?? "invalid_request";
  const errorDescription =
    typeof upstream.error_description === "string" && upstream.error_description
      ? upstream.error_description
      : error === "invalid_token"
        ? "The access token is invalid or expired"
        : "Missing bearer token. Authorize via OAuth using the resource metadata URL.";

  const code = error === "invalid_request" ? "authentication_required" : error;
  return problem({
    status: 401,
    code,
    title: code === "authentication_required" ? "Authentication required" : "Unauthorized",
    detail: errorDescription,
    headers: response.headers,
    extra: { error, error_description: errorDescription, resource_metadata: resourceMetadata },
  });
}

/**
 * mcp.CONNECT_CODE.8 — `?lang=<code>` on a page (the extension opens /connect with its UI language): the render gets it
 * as x-kaption-lang (the root layout's <html lang> and server text can't see the query), and the answer sets the
 * kaption_lang cookie (path /, SameSite=Lax, a year) so the sign-in page Claude or ChatGPT opens later speaks it too.
 * Done here rather than in Next middleware, which the OpenNext bundle can't load.
 */
export function withPageLanguage(req: Request): { request: Request; cookie: string | null } {
  if (req.method !== "GET") return { request: req, cookie: null };
  const url = new URL(req.url);
  const lang = normalizeLanguage(url.searchParams.get("lang"));
  if (!lang) return { request: req, cookie: null };
  const headers = new Headers(req.headers);
  headers.set(LANG_HEADER, lang);
  return { request: new Request(req, { headers }), cookie: languageCookie(lang, url.protocol === "https:") };
}

// ─── Factory: create the composed fetch handler ───────────────────────

interface WorkerHandler {
  fetch(request: Request, env: any, ctx: any): Promise<Response>;
}

/**
 * Security headers for responses served through the Next handler.
 *
 * These used to live in next.config.mjs as a `headers()` rule matching every
 * route, but such a rule is unrepresentable across this stack's two
 * path-to-regexp versions: Next 15.5's config validator rejects the v8 wildcard
 * '/*path' ("Unexpected MODIFIER"), while @opennextjs/cloudflare's
 * routingHandler runs path-to-regexp v8, which rejects the classic '/(.*)'
 * ("Unexpected ("). The v6 form '/:path*' fails under v8 too. Leaving '/(.*)'
 * in place made the router throw on EVERY dynamic request, so the whole site
 * returned 500 while static assets still served.
 *
 * Applying them here removes route matching from the equation entirely.
 */
export function applySecurityHeaders(headers: Headers): void {
  headers.set("X-Content-Type-Options", "nosniff");
  headers.set("X-Frame-Options", "DENY");
  headers.set("Referrer-Policy", "strict-origin-when-cross-origin");
  headers.set(
    "Content-Security-Policy",
    "default-src 'self'; script-src 'self' 'unsafe-inline' 'unsafe-eval'; "
      + "style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self' data:; "
      + "connect-src 'self' https://mcp.kaptionai.com https://mcp-ext.kaptionai.com",
  );
}

/**
 * OAuthProvider options — shared by the Worker and by the helpers that list
 * and revoke connections, because getOAuthApi needs the very same options.
 */
export function buildOAuthOptions(mcpOrigin: string, defaultHandler: unknown): OAuthProviderOptions<Env> {
  return {
    apiHandlers: {
      "/sse": sseHandler as any,
      "/mcp": mcpHandler as any,
    },
    authorizeEndpoint: "/authorize",
    tokenEndpoint: "/token",
    // Advertise registration endpoint in /.well-known/oauth-authorization-server
    // so MCP clients (Claude Code, Cursor, etc.) can auto-register
    clientRegistrationEndpoint: "/register",
    // mcp.CLOUD_RELAY.16 — registration stays open to every MCP client, but only with redirect URIs of known AI apps,
    // loopback (CLI/desktop clients) or a known desktop app's scheme (security report #2198).
    clientRegistrationCallback: checkClientRegistration,
    // Pin OAuth grants and access-token audiences to the trusted MCP hostname
    // the client selected. The provider also serves RFC 9728 metadata and
    // advertises it in 401 challenges for both the origin-level and
    // path-specific well-known URL.
    scopesSupported: ["kaption:access"],
    resourceMetadata: {
      resource: `${mcpOrigin}/mcp`,
      authorization_servers: [mcpOrigin],
      scopes_supported: ["kaption:access"],
      bearer_methods_supported: ["header"],
      resource_name: "Kaption AI",
    },
    // mcp.CLOUD_RELAY.9/10 — each connection lasts as long as the person chose
    // on the consent page. The library enforces only the fixed one-year choice
    // (a per-connection refreshTokenTTL set at the first token exchange);
    // "90 days without use" and "until I disconnect it" are open-ended here and
    // policed by connection-lifetime.ts. The library's own defaults — a refresh
    // token dying 30 days after connecting however much it was used, and a
    // client registration dying at 90 — are what forced people to reconnect.
    refreshTokenTTL: undefined,
    clientRegistrationTTL: undefined,
    tokenExchangeCallback: connectionLifetimeCallback,
    defaultHandler: defaultHandler as any,
  } as OAuthProviderOptions<Env>;
}

function escapeHtml(text: string): string {
  return text.replace(/[&<>"']/g, (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[ch]!);
}

/**
 * GET /authorize that cannot start. A browser (Accept: text/html — what
 * Claude or ChatGPT open) gets a small page with the localized sentence
 * (mcp.CLOUD_RELAY.18 — a page, never a bare 500 or plain text); any other
 * client gets the same sentence in a problem document.
 * mcp.CONNECT_CODE.8 — in the language /connect remembered, else the browser's.
 */
function authorizeError(
  req: Request,
  options: { englishDetail?: string; key?: string; code?: string } = {},
): Response {
  const { lang } = resolveLanguage({
    cookie: readCookie(req.headers.get("cookie"), LANG_COOKIE),
    acceptLanguage: req.headers.get("accept-language"),
  });
  const { englishDetail, key = "err.authorize_start", code = "invalid_authorization_request" } = options;
  const message = englishDetail ?? getT(lang)(key);
  const contentLanguage = englishDetail ? "en" : lang;
  if (acceptsHtml(req)) {
    const html = `<!doctype html><html lang="${escapeHtml(contentLanguage)}"><head><meta charset="utf-8">`
      + `<meta name="viewport" content="width=device-width, initial-scale=1"><title>Kaption</title>`
      + `<style>body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;`
      + `background:#0a0a0a;color:#e5e5e5;font:15px/1.5 system-ui,-apple-system,sans-serif;padding:20px;box-sizing:border-box}`
      + `main{max-width:420px;background:#171717;border:1px solid #262626;border-radius:12px;padding:28px}`
      + `h1{font-size:17px;margin:0 0 10px}p{margin:0;color:#a3a3a3}</style></head>`
      + `<body><main><h1>Kaption</h1><p data-testid="authorize-error">${escapeHtml(message)}</p></main></body></html>`;
    const headers = new Headers({
      "Content-Type": "text/html; charset=utf-8",
      "Content-Language": contentLanguage,
      "Cache-Control": "no-store",
    });
    applySecurityHeaders(headers);
    return new Response(html, { status: 400, headers });
  }
  return problem({
    status: 400,
    code,
    detail: message,
    headers: { "Content-Language": contentLanguage },
  });
}

/**
 * mcp.CLOUD_RELAY.18 — the RFC 8707 `resource` an MCP client names, as this server's one resource. Clients send the
 * address they were given: the legacy SSE address (`/sse`, `/sse?phone=…`) or the MCP address with a query
 * (`/mcp?phone=…`, mcp.CLOUD_RELAY.19's one-connector-per-number addresses). The library accepts only the exact
 * `<origin>/mcp`, so those sign-ins failed ("couldn't start signing in", #1735). Both paths reach the same server
 * on the same origin, so they are the same resource; anything else passes through for the library to judge.
 */
export function canonicalResource(value: string): string {
  try {
    const url = new URL(value);
    if (!MCP_ORIGINS.has(url.origin) || url.hash || url.username || url.password) return value;
    const path = url.pathname.replace(/\/+$/, "");
    if (path !== "/mcp" && path !== "/sse") return value;
    return `${url.origin}/mcp`;
  } catch {
    return value;
  }
}

/**
 * mcp.CLOUD_RELAY.18 — serves /sse for a valid, unexpired access token bound to `<origin>/mcp` (exactly what the
 * library demands on /mcp), with the grant's props as the library would set them. Null: let the library answer
 * (no token, an unknown or expired one, another audience) with its own challenge.
 */
export async function serveSseWithServerToken(
  request: Request,
  env: Env,
  ctx: ExecutionContext,
  mcpOrigin: string,
): Promise<Response | null> {
  const auth = request.headers.get("Authorization");
  if (!auth?.startsWith("Bearer ")) return null;
  let summary: Awaited<ReturnType<Env["OAUTH_PROVIDER"]["unwrapToken"]>> = null;
  try {
    summary = await env.OAUTH_PROVIDER.unwrapToken(auth.slice(7));
  } catch {
    return null;
  }
  if (!summary) return null;
  const audience = Array.isArray(summary.audience) && summary.audience.length === 1 ? summary.audience[0] : summary.audience;
  if (audience !== `${mcpOrigin}/mcp`) return null;
  (ctx as ExecutionContext & { props?: unknown }).props = summary.grant.props;
  return (sseHandler as unknown as WorkerHandler).fetch(request, env, ctx);
}

/** mcp.CLOUD_RELAY.18 — GET /authorize with its `resource` parameter(s) made canonical. */
export function withCanonicalAuthorizeResource(req: Request): Request {
  const url = new URL(req.url);
  const values = url.searchParams.getAll("resource");
  if (values.length === 0) return req;
  const canonical = values.map(canonicalResource);
  if (canonical.every((value, i) => value === values[i])) return req;
  url.searchParams.delete("resource");
  for (const value of canonical) url.searchParams.append("resource", value);
  return new Request(url.toString(), req);
}

/** mcp.CLOUD_RELAY.18 — POST /token (form body) with its `resource` parameter(s) made canonical. */
export async function withCanonicalTokenResource(req: Request): Promise<Request> {
  if (!/application\/x-www-form-urlencoded/i.test(req.headers.get("content-type") ?? "")) return req;
  const params = new URLSearchParams(await req.clone().text());
  const values = params.getAll("resource");
  if (values.length === 0) return req;
  const canonical = values.map(canonicalResource);
  if (canonical.every((value, i) => value === values[i])) return req;
  params.delete("resource");
  for (const value of canonical) params.append("resource", value);
  const headers = new Headers(req.headers);
  headers.delete("content-length");
  return new Request(req.url, { method: req.method, headers, body: params.toString() });
}

/**
 * The Worker's fetch handler. Every answer passes through the error
 * contract (src/problem.ts): non-JSON 4xx/5xx become problem documents, and
 * an exception becomes a 500 problem instead of Cloudflare's HTML error page.
 */
export function createFetchHandler(nextHandler: WorkerHandler) {
  const route = createRouter(nextHandler);
  return async function fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    let response: Response;
    try {
      response = await route(request, env, ctx);
    } catch (e: any) {
      console.error("[worker] unhandled error:", e?.message || e);
      return problem({ status: 500, code: "internal_error", detail: "Internal error" });
    }
    return ensureProblemJson(response, request);
  };
}

function createRouter(nextHandler: WorkerHandler) {
  return async function route(
    request: Request,
    env: Env,
    ctx: ExecutionContext,
  ): Promise<Response> {
    const url = new URL(request.url);
    const mcpOrigin = getMcpOrigin(url);

    // [L4] Propagate request ID
    const requestId =
      request.headers.get("x-request-id") || crypto.randomUUID();

    // The legacy hostname's home page competes in search with the site's MCP
    // page, so it redirects there. Only the page at "/" moves: the extension,
    // the desktop app and existing connections still use every other path here.
    if (
      url.origin === LEGACY_MCP_ORIGIN
      && url.pathname === "/"
      && (request.method === "GET" || request.method === "HEAD")
    ) {
      return Response.redirect(LEGACY_HOME_REDIRECT, 301);
    }

    // Public standards and domain-verification routes bypass OAuth.
    if (url.pathname === OPENAI_CHALLENGE_PATH) {
      return outerApp.fetch(request, env, ctx);
    }

    // Routes that bypass OAuth entirely
    if (url.pathname === "/ws/ext" || url.pathname === "/ws/auth") {
      return outerApp.fetch(request, env, ctx);
    }
    if (url.pathname.startsWith("/transparency")) {
      return outerApp.fetch(request, env, ctx);
    }
    if (url.pathname === "/ext/connections" || url.pathname.startsWith("/ext/connections/")) {
      return outerApp.fetch(request, env, ctx);
    }
    if (url.pathname.startsWith("/ext/connect-code/")) {
      return outerApp.fetch(request, env, ctx);
    }
    // mcp-usage-accounting.REPORT.1, LOCAL.5, ADMIN.1
    if (url.pathname === "/ext/usage" || url.pathname === "/ext/usage/local" || url.pathname === "/admin/usage") {
      return outerApp.fetch(request, env, ctx);
    }
    // Store phone hint by IP for pre-filling the authorize form.
    // The /sse?phone=X request comes from the CLI; /authorize opens in the
    // browser on the same machine → same IP.  Short TTL, harmless if stale.
    // mcp.CLOUD_RELAY.19 — /mcp?phone=X (one connector per number) pre-fills the same way. The phone here is only a
    // hint for the form: it never signs anyone in (mcp.CLOUD_RELAY.20).
    if ((url.pathname === "/sse" || url.pathname === "/mcp") && url.searchParams.has("phone")) {
      const ip = request.headers.get("cf-connecting-ip") || "unknown";
      const phone = url.searchParams.get("phone")!;
      ctx.waitUntil((async () => {
        const encryptedHint = await encryptLoginHint(phone, env.EPHEMERAL_STATE_SECRET);
        if (!encryptedHint) return;
        await env.OAUTH_KV.put(`login_hint:${ip}`, encryptedHint, { expirationTtl: 300 });
      })());
    }

    // OAuthProvider handles:
    // - /sse, /mcp → apiHandlers (OAuth token-protected MCP)
    // - /token → token exchange
    // - /register → RFC 7591 dynamic client registration
    // - Everything else → defaultHandler (Next.js)
    // mcp.CLOUD_RELAY.1 — OAuth 2.1 discovery, register, token endpoints
    // mcp.AUTH.2 — OAuthProvider validates bearer on every /sse + /mcp request
    const oauthOptions = buildOAuthOptions(mcpOrigin, {
      async fetch(
        req: Request,
        oauthEnv: Env,
        c: ExecutionContext,
      ): Promise<Response> {
        const reqUrl = new URL(req.url);

        // mcp.CLOUD_RELAY.2 — OTP phone flow; HMAC-signed oauthReqInfo
        // env.OAUTH_PROVIDER (OAuthHelpers) is available here inside defaultHandler
        let finalReq = req;
        if (reqUrl.pathname === "/authorize" && req.method === "GET") {
          try {
            const oauthReqInfo =
              await oauthEnv.OAUTH_PROVIDER.parseAuthRequest(req);
            if (!oauthReqInfo.clientId) {
              return authorizeError(req, { englishDetail: "Invalid authorization request" });
            }
            // mcp.CLOUD_RELAY.16 — a client registered before the redirect rule, with an address that isn't a known
            // AI app's, can't start a sign-in either (the library already checked it is one the client registered).
            if (!isAllowedRedirectUri(oauthReqInfo.redirectUri)) {
              console.warn("[authorize] sign-in refused: redirect not allowed for client", oauthReqInfo.clientId);
              return authorizeError(req, { key: "err.authorize_app_not_allowed", code: "unauthorized_client" });
            }
            const encoded = btoa(JSON.stringify(oauthReqInfo));
            const signed = await hmacSign(encoded, env.INTERNAL_API_KEY);
            const newUrl = new URL(req.url);
            newUrl.searchParams.set("_oauthReqInfo", signed);

            // Look up phone hint stored by /sse?phone= (same IP)
            const ip = req.headers.get("cf-connecting-ip") || "unknown";
            const encryptedHint = await env.OAUTH_KV.get(`login_hint:${ip}`);
            if (encryptedHint) {
              c.waitUntil(env.OAUTH_KV.delete(`login_hint:${ip}`));
              const phoneHint = await decryptLoginHint(
                encryptedHint,
                env.EPHEMERAL_STATE_SECRET,
              );
              if (phoneHint) {
                newUrl.searchParams.set("_loginHint", phoneHint);
              }
            }

            finalReq = new Request(newUrl.toString(), req);
          } catch (error) {
            // People see this page inside Claude or ChatGPT, so it says what to
            // do; the library's reason goes to the logs (wrangler tail).
            console.warn(
              "[authorize] sign-in request rejected:",
              error instanceof Error ? error.message : error,
            );
            return authorizeError(req);
          }
        }

        // mcp.CONNECT_CODE.8 — a page opened with ?lang= (the extension opens /connect so) keeps that language.
        const pageLang = withPageLanguage(finalReq);
        const response = await nextHandler.fetch(pageLang.request, oauthEnv, c);
        // [L4] Add request ID to response
        const newResponse = new Response(response.body, response);
        newResponse.headers.set("x-request-id", requestId);
        applySecurityHeaders(newResponse.headers);
        if (pageLang.cookie) newResponse.headers.append("Set-Cookie", pageLang.cookie);
        return newResponse;
      },
    });
    const oauthHandler = new OAuthProvider(oauthOptions);

    // The library caches its helpers on `env.OAUTH_PROVIDER` the first time a
    // request reaches the default handler, and the Worker's env object is
    // shared by every request an isolate serves. Our options differ by hostname
    // (each advertises its own resource), so helpers cached by a request on one
    // hostname rejected the other's sign-ins whenever the app sent its RFC 8707
    // `resource` — Claude and ChatGPT do — as invalid_target, shown as the
    // "Invalid authorization request" page, depending on which hostname the
    // isolate happened to serve first. Each request gets its own env, with
    // helpers built from its own options.
    const requestEnv: Env = { ...env };
    requestEnv.OAUTH_PROVIDER = getOAuthApi(oauthOptions, requestEnv);

    // mcp.CLOUD_RELAY.10/11 — connection lifetimes are enforced around the
    // token endpoint (connection-lifetime.ts).
    if (url.pathname === "/token" && request.method === "POST") {
      return handleTokenRequest(
        await withCanonicalTokenResource(request),
        requestEnv,
        ctx,
        (req) => oauthHandler.fetch(req, requestEnv, ctx),
        () => requestEnv.OAUTH_PROVIDER,
      );
    }

    // mcp.CLOUD_RELAY.18 — the legacy SSE address with a token issued for this server (audience <origin>/mcp, the only
    // resource the library issues for). The library's audience check compares the token with the request PATH, so
    // every such token was refused on /sse ("Token audience does not match resource server") and apps connected
    // through the SSE address re-authorized in a loop (#1735). Same checks as the library, then the SSE handler.
    if (url.pathname === "/sse" || url.pathname.startsWith("/sse/")) {
      const served = await serveSseWithServerToken(request, requestEnv, ctx, mcpOrigin);
      if (served) return served;
    }

    // mcp.CLOUD_RELAY.18 — /authorize names the canonical resource (the /sse or /mcp?… address the app was given).
    const oauthRequest = url.pathname === "/authorize" && request.method === "GET"
      ? withCanonicalAuthorizeResource(request)
      : request;
    return toJsonBearerChallenge(await oauthHandler.fetch(oauthRequest, requestEnv, ctx), url);
  };
}
